        assertEquals("tồi", composeWith("tooiszf") { liveSpellCheck = true; contextualEnglish = true })
        assertEquals("tôi", composeWith("tooisz") { liveSpellCheck = true; contextualEnglish = true })
        assertEquals("việt", composeWith("vieejtzj") { liveSpellCheck = true; contextualEnglish = true })
    }

    @Test fun testVNIZeroClearsThenToneReapplies() {
        assertEquals("tôi", composeWith("toi610") { vniMode = true })
        assertEquals("tối", composeWith("toi6101") { vniMode = true })
    }

    @Test fun testEnglishDoubleTapGestureUnchanged() {
        assertEquals("pizza", composeWith("pizza") { liveSpellCheck = true; contextualEnglish = true })
        assertEquals("jazz", composeWith("jazz") { liveSpellCheck = true; contextualEnglish = true })
        assertEquals("tested", commitWith("tessted") { liveSpellCheck = true; contextualEnglish = true })
        assertEquals("hosts", commitWith("hosts") { liveSpellCheck = true; contextualEnglish = true })
    }
}

