/** Ported from TelexCore/Tests/TelexCoreTests/ValidatorTests.swift. */
class ValidatorPortedTest {
    @Test fun testQuGlideKeepsTheUInTheRime() {
        assertTrue("isValidSyllable quyn", SyllableValidator.isValidSyllable("quyn"))
    }

    @Test fun testToneCodaConstraint() {
        assertTrue("isValidSyllable các", SyllableValidator.isValidSyllable("các"))
        assertTrue("isValidSyllable cạc", SyllableValidator.isValidSyllable("cạc"))
        assertFalse("isValidSyllable càc", SyllableValidator.isValidSyllable("càc"))
        assertFalse("isValidSyllable cảc", SyllableValidator.isValidSyllable("cảc"))
        assertFalse("isValidSyllable cãc", SyllableValidator.isValidSyllable("cãc"))
        assertFalse("isValidSyllable cac", SyllableValidator.isValidSyllable("cac"))
        assertTrue("isValidSyllable càn", SyllableValidator.isValidSyllable("càn"))
        assertTrue("isValidSyllable cạnh", SyllableValidator.isValidSyllable("cạnh"))
        assertTrue("isValidSyllable cảng", SyllableValidator.isValidSyllable("cảng"))
    }

    @Test fun testOnsetRules() {
        assertTrue("isValidSyllable nghe", SyllableValidator.isValidSyllable("nghe"))
        assertTrue("isValidSyllable nghĩ", SyllableValidator.isValidSyllable("nghĩ"))
        assertTrue("isValidSyllable quà", SyllableValidator.isValidSyllable("quà"))
        assertTrue("isValidSyllable gì", SyllableValidator.isValidSyllable("gì"))
        assertTrue("isValidSyllable gia", SyllableValidator.isValidSyllable("gia"))
        assertFalse("isValidSyllable fga", SyllableValidator.isValidSyllable("fga"))
        assertFalse("isValidSyllable ", SyllableValidator.isValidSyllable(""))
    }

    @Test fun testValidPrefixAcceptsRealWords() {
        assertTrue("isValidPrefix ", SyllableValidator.isValidPrefix(""))
    }

    @Test fun testValidSyllableStringFacadeEdges() {
        assertFalse("isValidSyllable ", SyllableValidator.isValidSyllable(""))
        assertTrue("isValidSyllable VIỆT", SyllableValidator.isValidSyllable("VIỆT"))
        assertTrue("isValidSyllable Người", SyllableValidator.isValidSyllable("Người"))
        assertFalse("isValidSyllable a1", SyllableValidator.isValidSyllable("a1"))
        assertFalse("isValidSyllable hó-a", SyllableValidator.isValidSyllable("hó-a"))
        assertFalse("isValidSyllable óá", SyllableValidator.isValidSyllable("óá"))
    }

    @Test fun testValidPrefixStringFacadeEdges() {
        assertTrue("isValidPrefix ", SyllableValidator.isValidPrefix(""))
        assertTrue("isValidPrefix NGƯ", SyllableValidator.isValidPrefix("NGƯ"))
        assertFalse("isValidPrefix a1", SyllableValidator.isValidPrefix("a1"))
    }
}
